CREATE OR REPLACE FUNCTION public.imp_verificar_transaccion() RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p uuid; s uuid; b uuid:=gen_random_uuid(); v jsonb; n integer; before_count bigint; before_prod bigint; BEGIN IF NOT public.imp_permiso('importar') THEN RAISE EXCEPTION 'Verificación solo adgral' USING ERRCODE='42501'; END IF; BEGIN SELECT count(*) INTO before_count FROM public.imp_bobinas; SELECT count(*) INTO before_prod FROM public.muestras_calidad; SELECT siguiente INTO n FROM public.imp_contador; IF n<>760 THEN RAISE EXCEPTION 'Verificación requiere contador 760 disponible'; END IF; p:=public.imp_catalogo_guardar('producto','QA_TRANSACCION_IMP','REFERENCE',null,null); SELECT id INTO s FROM public.imp_proveedores WHERE nombre='Continental'; v:=jsonb_build_object('producto_id',p,'proveedor_id',s,'sku','TEST_OVERRIDE+SKU','analista','PRUEBA TRANSACCIONAL','observaciones','Prueba revertida automáticamente','turno','1','planta_codigo','IXT','fecha','2026-10-24','estado','concesion','valores',jsonb_build_object('peso_base',null,'a',-0.82)); PERFORM public.imp_guardar(b,v,null,null); IF NOT EXISTS(SELECT 1 FROM public.imp_bobinas WHERE id=b AND folio='00760-00' AND sku='TEST_OVERRIDE+SKU' AND sku_referencia='REFERENCE' AND estado='concesion' AND valores->'peso_base'='null'::jsonb) THEN RAISE EXCEPTION 'Registro incorrecto'; END IF; PERFORM public.imp_guardar(b,v,null,null); IF (SELECT siguiente FROM public.imp_contador)<>761 OR (SELECT count(*) FROM public.imp_bobinas)<>before_count+1 THEN RAISE EXCEPTION 'Reintento consumió folio'; END IF; BEGIN PERFORM public.imp_guardar(gen_random_uuid(),v||'{"estado":"pendiente"}'::jsonb,null,null); RAISE EXCEPTION 'Estado inválido aceptado'; EXCEPTION WHEN check_violation THEN NULL; END; IF (SELECT siguiente FROM public.imp_contador)<>761 THEN RAISE EXCEPTION 'Error consumió folio'; END IF; PERFORM set_config('request.jwt.claim.sub','c17926d4-1407-40ff-8303-1d4c8bd9b4b4',true); IF NOT public.imp_permiso('capturar') OR public.imp_permiso('editar') OR public.imp_permiso('catalogo') THEN RAISE EXCEPTION 'Permisos capturista incorrectos'; END IF; BEGIN PERFORM public.imp_guardar(b,v,1,'Edición no autorizada prueba'); RAISE EXCEPTION 'Capturista pudo editar'; EXCEPTION WHEN insufficient_privilege THEN NULL; END; PERFORM public.imp_catalogo_guardar('proveedor','QA_PROVEEDOR_TRANSACCION',null,null,null); PERFORM set_config('request.jwt.claim.sub','eb5b4f7b-ec1c-4208-aee0-f38cb8a35d2f',true); IF NOT public.imp_permiso('editar') OR NOT public.imp_permiso('catalogo') THEN RAISE EXCEPTION 'Permisos Sinay incorrectos'; END IF; PERFORM public.imp_guardar(b,v||'{"sku":"SKU_EDITADO","estado":"rechazada"}'::jsonb,1,'Edición Calidad IXT prueba'); IF NOT EXISTS(SELECT 1 FROM public.imp_bobinas WHERE id=b AND revision=2 AND numero=760 AND sku='SKU_EDITADO' AND estado='rechazada') OR NOT EXISTS(SELECT 1 FROM public.imp_eventos WHERE bobina_id=b AND accion='edicion' AND antes->>'sku'='TEST_OVERRIDE+SKU' AND despues->>'sku'='SKU_EDITADO') THEN RAISE EXCEPTION 'Edición o trazabilidad incorrecta'; END IF; BEGIN PERFORM public.imp_guardar(b,v,1,'Edición concurrente prueba'); RAISE EXCEPTION 'Edición obsoleta aceptada' USING ERRCODE='PZ002'; EXCEPTION WHEN raise_exception THEN NULL; END; UPDATE public.imp_bobinas SET capturado_at=now()-interval '36 hours'-interval '1 second' WHERE id=b; BEGIN PERFORM public.imp_guardar(b,v,2,'Edición vencida prueba'); RAISE EXCEPTION 'Edición vencida aceptada' USING ERRCODE='PZ002'; EXCEPTION WHEN raise_exception THEN NULL; END; PERFORM set_config('request.jwt.claim.sub','ed274107-4b60-407c-9644-15ece4fa0232',true); IF NOT public.imp_permiso('catalogo') THEN RAISE EXCEPTION 'Permisos Karina incorrectos'; END IF; IF (SELECT count(*) FROM public.muestras_calidad)<>before_prod THEN RAISE EXCEPTION 'Fabricación alterada'; END IF; PERFORM set_config('request.jwt.claim.sub','',true); PERFORM set_config('request.jwt.claims','{}',true); IF public.imp_permiso('leer') OR public.imp_permiso('capturar') THEN RAISE EXCEPTION 'Acceso anónimo permitido'; END IF; RAISE EXCEPTION 'PASS' USING ERRCODE='PZ001'; EXCEPTION WHEN SQLSTATE 'PZ001' THEN RETURN 'PASS: captura 00760-00, SKU distinto, nulos, estados, reintento, fallo sin hueco, permisos capturista/Calidad, edición auditada, concurrencia, ventana 36 h, bloqueo anónimo, fabricación intacta. Todo revertido.'; END; END $$;